-- Новые вопросы тем 05–08 (близко к лекциям курса DBA1) с пояснениями к каждому варианту.
-- Повторный запуск безопасен: вопрос с тем же текстом не добавляется второй раз.

BEGIN;

INSERT INTO questions (category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM (
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Транзакция на уровне Repeatable Read уже построила снимок. Затем другая транзакция удалила строку и зафиксировала изменение. Увидит ли первая транзакция эту строку при повторном запросе?', '{"A":"Да: в её снимке строка ещё существует","B":"Нет: удаление уже зафиксировано","C":"Запрос завершится ошибкой сериализации","D":"Запрос будет ждать завершения удаляющей транзакции"}'::jsonb, 'A', 'Это правильное поведение: снимок даёт согласованную картину на выбранный момент.', '{"A":"Снимок построен до удаления, и транзакция видит согласованную картину на тот момент.","B":"Так было бы на Read Committed, где снимок строится для каждого оператора.","C":"Ошибка возможна при попытке изменить такую строку, а не при чтении.","D":"Обычное чтение не ждёт изменяющих транзакций; к тому же та транзакция уже завершена."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'В таблице одна строка. Транзакция A на уровне Read Committed прочитала её. Транзакция B удалила строку и зафиксировала изменение. Сколько строк увидит A, повторив тот же запрос?', '{"A":"Запрос завершится ошибкой","B":"Одну","C":"A будет ждать окончания транзакции B","D":"Ноль"}'::jsonb, 'D', 'Поэтому на Read Committed два одинаковых запроса в одной транзакции могут вернуть разные данные.', '{"A":"Чтение на Read Committed не приводит к ошибкам сериализации.","B":"Так будет на уровне Repeatable Read, где снимок один на всю транзакцию.","C":"B уже завершена, ждать нечего; к тому же обычное чтение не ждёт изменяющих транзакций.","D":"На Read Committed снимок строится заново для каждого оператора, и удаление уже видно."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Что должно уметь приложение, работающее на уровне изоляции Serializable?', '{"A":"Выполнять каждую команду в отдельной транзакции","B":"Работать в каждой транзакции только с одной таблицей","C":"Явно блокировать все читаемые строки","D":"Повторять транзакции, прерванные ошибкой сериализации"}'::jsonb, 'D', 'Зато операторы можно писать так, как будто транзакция работает одна.', '{"A":"Смысл уровня как раз в изоляции многооператорных транзакций.","B":"Такого ограничения нет.","C":"Не требуется: уровень сам обеспечивает полную изоляцию.","D":"Часть транзакций на этом уровне прерывается, и это нормально."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Чем помечается версия строки при её создании?', '{"A":"Номером страницы, на которой она лежит","B":"Временем по часам сервера","C":"Номером транзакции, создавшей эту версию (командой INSERT или UPDATE)","D":"Номером последней контрольной точки"}'::jsonb, 'C', 'При удалении версия помечается номером удалившей транзакции, UPDATE — это DELETE и INSERT.', '{"A":"Положение версии на странице не определяет её время действия.","B":"Вместо времени используются возрастающие номера транзакций.","C":"Время действия версий измеряется номерами транзакций.","D":"Контрольные точки к видимости версий не относятся."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Что происходит с версией строки при выполнении DELETE?', '{"A":"Она переносится в toast-таблицу","B":"Она переносится в журнал предзаписи","C":"Она помечается номером удалившей транзакции и физически остаётся на месте","D":"Она сразу физически удаляется со страницы"}'::jsonb, 'C', 'Поэтому в таблицах накапливаются мёртвые версии и нужна очистка.', '{"A":"TOAST служит для длинных значений, а не для удалённых строк.","B":"В журнал пишется запись об изменении, сама версия остаётся в таблице.","C":"Её ещё могут видеть другие снимки, а при откате она снова станет актуальной.","D":"Физически мёртвые версии позже убирает очистка."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'На каком уровне определяется горизонт очистки?', '{"A":"Один на весь кластер","B":"Отдельно для каждого сеанса","C":"Отдельно для каждой базы данных","D":"Отдельно для каждой таблицы"}'::jsonb, 'C', 'Версии, удалённые транзакциями до горизонта, уже не видны ни в одном снимке и могут быть вычищены.', '{"A":"В курсе горизонт рассматривается для каждой базы отдельно.","B":"Сеанс лишь может удерживать горизонт своей долгой транзакцией.","C":"Так сказано в курсе: горизонт один на каждую базу данных.","D":"Горизонт определяется по транзакциям базы, а не по таблице."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Для чего нужны блокировки на уровне таблиц?', '{"A":"Чтобы запретить доступ к таблице на время её перестроения","B":"Чтобы снимать блокировки строк сразу после выполнения оператора","C":"Чтобы никто не удалил таблицу, пока другие транзакции читают из неё","D":"Чтобы запретить чтение строк, которые сейчас изменяются"}'::jsonb, 'AC', 'На практике удаление и перестроение таблиц выполняются редко и обычно не мешают работе.', '{"A":"Перестроение, в том числе неявное при изменении структуры, полностью блокирует доступ.","B":"Блокировки снимаются при завершении транзакции или при откате к точке сохранения, после которой они получены.","C":"Такая блокировка защищает таблицу от удаления во время работы с ней.","D":"Изменение строки не блокирует её чтение."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', '{"A":"Таблица удалится сразу","B":"DROP TABLE будет ждать завершения транзакции A","C":"DROP TABLE сразу завершится ошибкой","D":"Транзакция A будет прервана"}'::jsonb, 'B', 'Это одно из заданий практики курса.', '{"A":"Блокировка уровня таблицы этого не позволит.","B":"Удалить таблицу, с которой работает другая транзакция, нельзя до её завершения.","C":"По умолчанию команда ждёт блокировку (если не задан lock_timeout).","D":"Ждёт тот, кто запрашивает несовместимую блокировку, а не наоборот."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Транзакция в первом сеансе создала таблицу и вставила строку, но не зафиксировала изменения. Что получит второй сеанс при запросе к этой таблице?', '{"A":"Одну строку","B":"Пустую таблицу","C":"Ошибку: таблица не существует","D":"Запрос будет ждать фиксации первой транзакции"}'::jsonb, 'C', 'После фиксации таблица и строка станут видны, после отката таблицы не будет вовсе.', '{"A":"Незафиксированные изменения другим транзакциям не видны.","B":"Не видна даже сама таблица: её описание в системном каталоге тоже не зафиксировано.","C":"Незафиксированное создание таблицы другим сеансам не видно.","D":"Запрос не ждёт: таблица просто не найдена."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Обычная блокировка строки или таблицы была получена после установки точки сохранения. Когда она будет снята при откате к этой точке?', '{"A":"Через время, заданное deadlock_timeout","B":"Никогда, её нужно снять вручную","C":"Сразу при откате к точке сохранения","D":"Только при завершении всей транзакции"}'::jsonb, 'C', 'В остальных случаях блокировки снимаются при завершении транзакции.', '{"A":"Этот параметр относится к проверке взаимоблокировок.","B":"Все блокировки снимаются автоматически.","C":"Так блокировки, полученные после точки сохранения, освобождаются раньше конца транзакции.","D":"Это верно для остальных блокировок, но не для полученных после точки сохранения."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Две транзакции на уровне Read Committed пытаются изменить одну и ту же строку. Что произойдёт?', '{"A":"Обе изменят каждая свою версию строки","B":"Вторая сразу получит ошибку","C":"Изменения обеих смешаются","D":"Вторая будет ждать, пока первая завершится"}'::jsonb, 'D', 'Это единственный случай, когда транзакция ждёт блокировку строки.', '{"A":"Свою версию видят читающие транзакции; изменения одной строки идут по очереди.","B":"На Read Committed она дождётся; ошибки сериализации возможны на более строгих уровнях.","C":"Изменения выполняются последовательно и не смешиваются.","D":"Затем вторая перепроверит строку и изменит её, если та всё ещё подходит под условие."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Допишите команду, чтобы узнать уровень изоляции текущей транзакции:
```
SHOW ___;
```', '{"A":"`transaction_level`","B":"`transaction_isolation`","C":"`isolation_level`","D":"`default_isolation`"}'::jsonb, 'B', 'Уровень по умолчанию для новых транзакций задаёт default_transaction_isolation.', '{"A":"Такого параметра нет.","B":"Параметр отражает уровень изоляции текущей транзакции.","C":"Такого параметра нет.","D":"Такого параметра нет; есть default_transaction_isolation."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Допишите команду, чтобы все новые транзакции сеанса по умолчанию работали на уровне Repeatable Read:
```
SET ___ = ''repeatable read'';
```', '{"A":"`transaction_isolation`","B":"`isolation_level`","C":"`session_isolation`","D":"`default_transaction_isolation`"}'::jsonb, 'D', 'По умолчанию используется Read Committed.', '{"A":"Относится к текущей транзакции и задаётся в её начале, а не на будущее.","B":"Такого параметра нет.","C":"Такого параметра нет.","D":"Задаёт уровень изоляции по умолчанию для новых транзакций."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '05.'), 'Что такое «грязное чтение»?', '{"A":"Чтение строк, которые уже вычистила очистка","B":"Чтение изменений другой транзакции, которые ещё не зафиксированы","C":"Повторное чтение, вернувшее другие данные","D":"Чтение данных из грязного буфера"}'::jsonb, 'B', 'Грязное чтение плохо тем, что изменения могут быть отменены.', '{"A":"Вычищенные версии уже не видны ни в одном снимке.","B":"Стандарт SQL допускает его на уровне Read Uncommitted, но в PostgreSQL этот уровень работает как Read Committed, и грязных чтений нет.","C":"Это неповторяющееся (или фантомное) чтение, оно возможно на Read Committed.","D":"Грязный буфер — изменённая страница в памяти; это другое понятие."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Для чего служит карта свободного пространства таблицы?', '{"A":"Хранит мёртвые версии строк до очистки","B":"Показывает свободное место на диске","C":"Отмечает свободное место в страницах и помогает быстро найти место для новых версий строк","D":"Отмечает страницы, где все версии видны во всех снимках"}'::jsonb, 'C', 'Для ускорения поиска карта имеет древовидную структуру.', '{"A":"Мёртвые версии лежат в самих страницах таблицы.","B":"Свободное место на диске смотрят средствами ОС, например df.","C":"Объём меняется: при вставке уменьшается, при очистке растёт.","D":"Это карта видимости."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Что отмечается в карте свободного пространства индекса?', '{"A":"Свободное место в каждой странице","B":"Страницы с замороженными записями","C":"Только полностью пустые страницы, которые можно использовать заново","D":"Ничего: у индексов нет карты свободного пространства"}'::jsonb, 'C', 'Пустые страницы исключаются из структуры индекса и потом подключаются в подходящее место.', '{"A":"Так устроена карта для таблиц, а не для индексов.","B":"Заморозка относится к версиям строк таблиц.","C":"Индексная запись вставляется в строго определённое место, поэтому частично свободное место не учитывается.","D":"У индексов нет карты видимости, а карта свободного пространства у них есть (например, у B-деревьев)."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Как карта видимости ускоряет доступ только по индексу?', '{"A":"Сжимает индекс","B":"Если страница отмечена, видимость строки не нужно проверять по таблице","C":"Отмечает пустые страницы индекса","D":"Хранит копии индексных записей"}'::jsonb, 'B', 'Если карту не обновлять, индексный доступ работает менее эффективно.', '{"A":"Карта видимости размер индекса не меняет.","B":"Когда все нужные столбцы есть в индексе, к таблице можно не обращаться.","C":"Это делает карта свободного пространства индекса.","D":"Карта видимости хранит лишь биты для страниц таблицы."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Как карта видимости помогает самой очистке?', '{"A":"Никак не помогает","B":"Очистка обрабатывает только отмеченные страницы","C":"Очистка может пропускать страницы, отмеченные в карте видимости","D":"Определяет порядок обработки таблиц"}'::jsonb, 'C', 'Отмечены страницы, которые давно не менялись и полностью очищены.', '{"A":"Это одно из двух главных применений карты видимости.","B":"Наоборот: отмеченные страницы можно пропустить.","C":"В таких страницах нет мёртвых версий; заморозка всё же заглядывает в страницы, ещё не отмеченные как полностью замороженные.","D":"Карта видимости порядок не задаёт: автоочистка выбирает таблицы по объёму изменений."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Как PostgreSQL собирает статистику для планировщика?', '{"A":"Только по индексам таблицы","B":"Полным чтением всех строк таблицы","C":"Из записей журнала предзаписи","D":"По случайной выборке данных таблицы"}'::jsonb, 'D', 'Достаточно, чтобы статистика периодически обновлялась и не слишком отличалась от действительности.', '{"A":"Статистика собирается по данным таблицы.","B":"На больших таблицах это слишком долго, а точная статистика и не нужна.","C":"Журнал хранит изменения для восстановления, а не статистику.","D":"Так быстро получается приближённая статистика даже по очень большим таблицам."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Что означает, что версия строки заморожена?', '{"A":"Она ждёт удаления очисткой","B":"Её больше нельзя изменить или удалить","C":"Создавшая её транзакция считается завершённой в прошлом для любого снимка, и её номер больше не важен","D":"Она перенесена в архив"}'::jsonb, 'C', 'Заморозка защищает от последствий переполнения 32-битного счётчика транзакций.', '{"A":"Удаления ждут мёртвые версии, а не замороженные.","B":"Замороженную версию можно обновить или удалить, как обычную.","C":"Этот номер можно использовать повторно после перехода счётчика через ноль.","D":"Заморозка — признак версии, сама версия остаётся на месте."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Что отмечает дополнительный бит в карте видимости?', '{"A":"Страницы с мёртвыми версиями строк","B":"Страницы, на которых все версии строк уже заморожены","C":"Полностью пустые страницы","D":"Страницы, изменённые после контрольной точки"}'::jsonb, 'B', 'Основной бит отмечает страницы, где все версии видны во всех снимках.', '{"A":"Карта видимости отмечает, наоборот, страницы без мёртвых версий.","B":"Это позволяет не просматривать лишние страницы при заморозке.","C":"Пустые страницы учитывает карта свободного пространства.","D":"Это к карте видимости не относится."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Чем автоочистка лучше очистки по расписанию?', '{"A":"Блокирует таблицы, чтобы работать быстрее","B":"Совсем не создаёт нагрузки на ввод-вывод","C":"Возвращает освободившееся место операционной системе","D":"Реагирует на активность изменений: активные таблицы обрабатываются чаще"}'::jsonb, 'D', 'Автоочистка должна работать, но требует настройки.', '{"A":"Очистка работает постранично и обычно не мешает чтению и изменению строк; ненадолго блокирует таблицу лишь при отсечении пустого конца.","B":"Нагрузку на ввод-вывод она создаёт, хотя обычно не мешает чтению и изменению строк.","C":"Обычная очистка место ОС, как правило, не возвращает.","D":"Расписание либо создаёт лишнюю нагрузку, либо не успевает за изменениями."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'К чему приводит отключение автоочистки, если не выполнять очистку и анализ вручную?', '{"A":"К неконтролируемому разрастанию таблиц и индексов","B":"К замедлению поиска актуальных версий строк","C":"К устаревшей статистике и плохим планам запросов","D":"К заметному ускорению запросов"}'::jsonb, 'ABC', 'Автоочистка не работает, если выключен параметр autovacuum или track_counts.', '{"A":"Мёртвые версии накапливаются: при обычной работе вычищается лишь малая их часть.","B":"Мёртвые версии приходится просматривать вместе с живыми.","C":"Анализ тоже выполняет автоочистка.","D":"Кажущаяся экономия ввода-вывода оборачивается гораздо худшими последствиями."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Почему индекс-B-дерево не уменьшается даже после удаления большинства записей?', '{"A":"Страницы, получившиеся при расщеплении, больше не объединяются","B":"Индексы вообще не очищаются","C":"Удалённые записи переносятся в toast-таблицу","D":"Размер индекса фиксируется при его создании"}'::jsonb, 'A', 'Уменьшить индекс помогает перестроение командой REINDEX.', '{"A":"Даже если из них удалены все индексные записи.","B":"Очистка убирает из индексов ссылки на мёртвые версии строк.","C":"TOAST к индексным записям не относится.","D":"Индекс растёт по мере добавления записей."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Что блокирует команда REINDEX?', '{"A":"Только чтение таблицы","B":"Запись в таблицу и использование перестраиваемого индекса","C":"Ничего не блокирует","D":"Работу всего кластера"}'::jsonb, 'B', 'Неблокирующий вариант выполняется дольше и может завершиться неудачно.', '{"A":"Блокируется запись в таблицу и использование индекса.","B":"Транзакции, изменяющие таблицу или планирующие запрос к ней, будут приостановлены.","C":"Без блокировки изменений работает REINDEX CONCURRENTLY.","D":"Блокировки касаются только таблицы и её индекса."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Какое стороннее расширение позволяет перестроить таблицу и её индексы без долгой исключительной блокировки?', '{"A":"`pg_buffercache`","B":"`pg_stat_statements`","C":"`pgstattuple`","D":"`pg_repack`"}'::jsonb, 'D', 'VACUUM FULL тоже перестраивает таблицу, но требует исключительной блокировки.', '{"A":"Показывает содержимое буферного кеша.","B":"Собирает статистику по выполняемым запросам.","C":"Показывает статистику по версиям строк, например долю мёртвых.","D":"Перестраивает таблицу «на лету»."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Допишите запрос, чтобы узнать суммарный размер индексов таблицы t:
```
SELECT ___(''t'');
```', '{"A":"`pg_table_size`","B":"`pg_relation_size`","C":"`pg_indexes_size`","D":"`pg_total_relation_size`"}'::jsonb, 'C', 'В практике курса так следят за разрастанием таблицы и индекса.', '{"A":"Размер таблицы с её TOAST-частью, без индексов.","B":"Размер одного слоя отношения.","C":"Суммирует размеры всех индексов таблицы.","D":"Полный размер таблицы вместе с индексами."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Допишите команду из практики курса, чтобы выключить автоочистку (затем конфигурацию нужно перечитать):
```
ALTER SYSTEM SET autovacuum = ___;
```', '{"A":"`off`","B":"`none`","C":"`never`","D":"`disabled`"}'::jsonb, 'A', 'Вернуть значение по умолчанию можно командой ALTER SYSTEM RESET autovacuum.', '{"A":"Логический параметр принимает on/off; в рабочей системе выключать автоочистку нельзя.","B":"Недопустимое значение для логического параметра.","C":"Недопустимое значение для логического параметра.","D":"Недопустимое значение для логического параметра."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Что хранит буфер в буферном кеше, кроме самой страницы данных?', '{"A":"Сжатую копию соседних страниц","B":"Копию журнальной записи об изменении страницы","C":"Снимок данных, в котором страница была прочитана","D":"Дополнительную информацию, например имя файла и положение страницы в нём"}'::jsonb, 'D', 'Размер страницы обычно 8 Кбайт и меняется только при сборке.', '{"A":"Буфер содержит одну страницу.","B":"Журнальные записи хранятся в буферах журнала.","C":"Снимки принадлежат транзакциям, а не буферам.","D":"По ней понятно, какая страница лежит в буфере."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Почему обращение к буферному кешу медленнее простого обращения к оперативной памяти?', '{"A":"Буферный кеш хранится на диске","B":"Буферы защищены блокировками для совместного доступа","C":"Каждое обращение идёт через операционную систему","D":"Страницы в кеше хранятся сжатыми"}'::jsonb, 'B', 'Поэтому чем меньше данных читает и меняет запрос, тем быстрее он работает.', '{"A":"Буферный кеш находится в общей памяти.","B":"Блокировки реализованы эффективно, но всё же требуют времени.","C":"Через ОС идут чтение отсутствующих страниц и запись грязных буферов, а не каждое обращение к кешу.","D":"Страницы хранятся в кеше без сжатия."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Почему изменённая страница записывается на диск не сразу?', '{"A":"Чтобы реплики успели её прочитать","B":"Страницы пишутся на диск только при остановке сервера","C":"Её должна сначала проверить очистка","D":"Ради производительности: запись асинхронна и может откладываться"}'::jsonb, 'D', 'Такой буфер называют грязным.', '{"A":"Реплики получают журнальные записи, а не страницы.","B":"Их записывают контрольные точки, фоновая запись и вытеснение.","C":"Перед записью страницы на диск никакая проверка очисткой не требуется.","D":"Надёжность при этом обеспечивает журнал."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Процессу нужна страница, которой нет в буферном кеше. Что он делает?', '{"A":"Просит ОС прочитать её и помещает в буферный кеш","B":"Ждёт ближайшей контрольной точки","C":"Возвращает ошибку","D":"Читает её с диска напрямую, минуя ОС"}'::jsonb, 'A', 'Если места в кеше нет, сначала вытесняется давно не использовавшаяся страница.', '{"A":"ОС может прочитать страницу с диска или найти её в собственном кеше.","B":"Контрольная точка записывает грязные буферы и чтению не нужна.","C":"Отсутствие страницы в кеше — обычная ситуация.","D":"PostgreSQL работает с диском через операционную систему."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Почему запись через журнал эффективнее, чем запись каждой изменённой страницы сразу на диск?', '{"A":"Журнальные записи обычно меньше целой страницы данных","B":"Журнал читается при каждом запросе","C":"Журнал не нужно сбрасывать на диск","D":"Журнал записывается строго последовательно"}'::jsonb, 'AD', 'На эффективность можно влиять, выбирая синхронный или асинхронный режим.', '{"A":"Записывается минимально необходимая информация, хотя в журнал может попасть и полный образ страницы, например при первом её изменении после контрольной точки.","B":"Журнал обычно не читается, пока не случится сбой.","C":"Наоборот, записи должны попасть на диск раньше изменённых данных.","D":"С последовательной записью справляются даже простые HDD."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Какой системный вызов (или его вариант) PostgreSQL использует, чтобы журнальная запись не осталась в кеше ОС?', '{"A":"`select`","B":"`mmap`","C":"`fsync`","D":"`fork`"}'::jsonb, 'C', 'Пока идёт такая запись, процесс, выполняющий фиксацию, вынужден ждать.', '{"A":"Ожидает события ввода-вывода.","B":"Отображает файл в память, а не гарантирует запись на носитель.","C":"PostgreSQL полагается на него или его варианты; метод задаёт параметр wal_sync_method.","D":"Порождает процесс: так postmaster запускает обслуживающие процессы."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Чем рискует асинхронный режим фиксации?', '{"A":"Каждая транзакция откатывается при сбое реплики","B":"Ничем: это то же самое, что синхронный режим","C":"Можно потерять несколько последних зафиксированных транзакций, но согласованность после сбоя сохранится","D":"Данные после сбоя могут стать несогласованными"}'::jsonb, 'C', 'На практике оба режима работают совместно.', '{"A":"Режим фиксации к репликам так не относится.","B":"Надёжность уменьшается, зато растёт производительность.","C":"Записи журнала пишет фоновый процесс walwriter с небольшой задержкой.","D":"Восстановление согласованности гарантируется и в этом режиме."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Страница данных сбрасывается на диск, а соответствующая ей журнальная запись ещё не записана. Что произойдёт?', '{"A":"Страница запишется, а журнальная запись позже","B":"Сброс страницы отложится до контрольной точки","C":"Сервер остановится с ошибкой","D":"Журнальная запись будет сразу записана в синхронном режиме"}'::jsonb, 'D', 'Поэтому синхронный и асинхронный режимы записи журнала работают совместно.', '{"A":"Это нарушило бы главное правило журнала предзаписи.","B":"Нужная журнальная запись просто записывается немедленно.","C":"Это штатная ситуация.","D":"Журнал всегда должен попасть на диск раньше данных."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Какие обычные транзакции после восстановления после сбоя считаются оборванными?', '{"A":"Те, запись о фиксации которых не успела попасть в журнал","B":"Все, что были активны в момент контрольной точки","C":"Все, начатые после последней контрольной точки","D":"Никакие"}'::jsonb, 'A', 'Восстановление начинается с последней завершённой контрольной точки.', '{"A":"Работа остальных восстанавливается проигрыванием журнала.","B":"Значение имеет только запись о фиксации в журнале.","C":"Зафиксированные после неё восстанавливаются по журналу.","D":"Незафиксированные к моменту сбоя транзакции обрываются."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Когда контрольная точка считается выполненной?', '{"A":"Когда записаны все буферы, которые были грязными в момент её начала","B":"В момент её начала","C":"Когда журнал скопирован в архив","D":"Когда буферный кеш полностью очищен"}'::jsonb, 'A', 'Контрольная точка сбрасывает и буферы clog со статусами транзакций.', '{"A":"Это гарантирует, что все изменения до этого момента уже на диске.","B":"Сама «точка» — момент начала, но выполненной она считается только после записи.","C":"Архивирование журнала к контрольной точке не относится.","D":"Буферы остаются в кеше, просто становятся чистыми."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Что добавляет в журнал уровень replica по сравнению с minimal?', '{"A":"Ничего: это синонимы","B":"Информацию для логической репликации","C":"Информацию, позволяющую делать резервные копии и репликацию","D":"Тексты выполненных запросов"}'::jsonb, 'C', 'Уровень replica используется по умолчанию.', '{"A":"На уровне minimal часть изменений в журнал не попадает.","B":"Её добавляет уровень logical.","C":"На уровне minimal журнал обеспечивает только восстановление после сбоя.","D":"Журнал содержит изменения данных, а не тексты запросов."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Допишите команду, чтобы журнал позволял настроить логическую репликацию (после неё нужен перезапуск сервера):
```
ALTER SYSTEM SET wal_level = ___;
```', '{"A":"`logical`","B":"`replica`","C":"`minimal`","D":"`full`"}'::jsonb, 'A', 'Параметр wal_level меняется только с перезапуском сервера.', '{"A":"Добавляет в журнал информацию для декодирования изменений строк.","B":"Достаточно для резервных копий и физической репликации, но не для логической.","C":"Обеспечивает только восстановление после сбоя.","D":"Такого значения у wal_level нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Что делает сервер при остановке в режиме fast?', '{"A":"Сразу запускается снова","B":"Ждёт, пока все клиенты отключатся сами","C":"Обрывает открытые соединения и перед выключением выполняет контрольную точку","D":"Выключается без контрольной точки"}'::jsonb, 'C', 'В Ubuntu такую остановку выполняет pg_ctlcluster 16 main stop.', '{"A":"Это остановка, а не перезапуск.","B":"Так работает режим smart.","C":"Поэтому при следующем запуске сервер сразу готов к работе.","D":"Это режим immediate."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '07.'), 'Сервер был остановлен в режиме immediate. Что произойдёт при следующем запуске?', '{"A":"Сервер восстановит согласованность данных по журналу","B":"Журнал будет удалён","C":"Потребуется вручную выполнить pg_resetwal","D":"Сервер сразу будет готов к работе без восстановления"}'::jsonb, 'A', 'В журнале сообщений это видно как восстановление после сбоя.', '{"A":"На диске остались несогласованные данные, как после сбоя.","B":"Именно журнал нужен для восстановления.","C":"Это утилита для крайних случаев, штатное восстановление её не требует.","D":"Так бывает после остановки в режиме fast."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Как создаётся новая база данных?', '{"A":"Клонированием существующей базы, по умолчанию template1","B":"С нуля по описанию из postgresql.conf","C":"Восстановлением шаблона утилитой pg_restore","D":"Утилитой initdb"}'::jsonb, 'A', 'Шаблон можно указать явно, например template0.', '{"A":"Все базы, кроме созданных при инициализации кластера, клонируются.","B":"В файлах конфигурации базы данных не описываются.","C":"pg_restore восстанавливает резервные копии.","D":"initdb создаёт кластер с тремя базами, а не отдельную базу."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Для чего нужны схемы?', '{"A":"Чтобы разрешать или запрещать подключение к базе","B":"Чтобы предотвратить конфликты имён между пользователями и приложениями","C":"Чтобы управлять физическим размещением данных на дисках","D":"Чтобы разделить объекты базы на логические группы"}'::jsonb, 'BD', 'Каждый объект базы данных принадлежит какой-либо схеме.', '{"A":"Подключение регулируют привилегия CONNECT и pg_hba.conf.","B":"Одинаковые имена могут жить в разных схемах.","C":"Это задача табличных пространств.","D":"Так объектами удобнее управлять."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Какие схемы обычно есть в каждой базе данных?', '{"A":"`public`","B":"`information_schema`","C":"`pg_default`","D":"`pg_catalog`"}'::jsonb, 'ABD', 'Кроме них есть технические схемы, например временные pg_temp_N.', '{"A":"Схема по умолчанию для объектов пользователей.","B":"Представление системного каталога по стандарту SQL.","C":"Это табличное пространство, а не схема.","D":"Схема объектов системного каталога."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Что верно для схемы с именем пользователя в пути поиска по умолчанию?', '{"A":"Это другое имя схемы public","B":"Она создаётся автоматически вместе с ролью","C":"Её нельзя создать вручную","D":"Она входит в путь поиска, но сама не создаётся"}'::jsonb, 'D', 'В пути поиска она обозначается как "$user".', '{"A":"Это отдельная схема, совпадающая по имени с пользователем.","B":"Схему нужно создать явно.","C":"Её можно создать командой CREATE SCHEMA.","D":"Если её создать и у пользователя есть права на неё, новые объекты без указания схемы будут попадать в неё."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Что изменилось для схемы public начиная с PostgreSQL 15?', '{"A":"Её переименовали","B":"Её больше нет в новых базах","C":"Начальные права доступа к ней ограничены","D":"Она стала частью системного каталога"}'::jsonb, 'C', 'Если ничего не менять и есть доступ к схеме public, объекты создаются в ней.', '{"A":"Имя осталось прежним.","B":"Схема public по-прежнему есть.","C":"Раньше создавать в ней объекты мог любой пользователь.","D":"Системный каталог находится в pg_catalog."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Как обратиться к временной схеме текущего сеанса, не зная её номера?', '{"A":"По имени pg_temp","B":"По имени temp","C":"По имени public","D":"По имени pg_temp_0"}'::jsonb, 'A', 'Временная схема создаётся автоматически при создании первой временной таблицы.', '{"A":"Для каждого сеанса это имя ссылается на его собственную временную схему.","B":"Это имя не является псевдонимом временной схемы; для этого служит pg_temp.","C":"Это обычная схема, общая для всех.","D":"Номер временной схемы у каждого сеанса свой."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Если pg_temp не указана в search_path, где она подразумевается при поиске таблиц?', '{"A":"Перед всеми остальными схемами","B":"Сразу после pg_catalog","C":"Нигде: без явного указания она не просматривается","D":"После всех схем пути поиска"}'::jsonb, 'A', 'Обе схемы можно указать в пути явно на нужном месте.', '{"A":"Временные объекты сеанса находятся раньше других.","B":"Неявно первой идёт pg_temp, затем pg_catalog, если её место не указано в пути явно.","C":"Она просматривается и без явного указания.","D":"Неявно она проверяется первой."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Допишите команду, чтобы создать таблицу, которая существует только в текущем сеансе:
```
CREATE ___ TABLE t (id int);
```', '{"A":"`UNLOGGED`","B":"`SESSION`","C":"`PRIVATE`","D":"`TEMP`"}'::jsonb, 'D', 'Можно также ограничить время жизни таблицы транзакцией.', '{"A":"Не журналируется и видна всем сеансам; таблица сохраняется между сеансами, но после сбоя её данные очищаются.","B":"Такого слова в команде CREATE TABLE нет.","C":"Такого слова в команде CREATE TABLE нет.","D":"Временная таблица видна только своему сеансу и удаляется по его окончании."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Допишите запрос, чтобы узнать размер базы данных appdb:
```
SELECT pg_size_pretty(___(''appdb''));
```', '{"A":"`pg_tablespace_size`","B":"`pg_total_relation_size`","C":"`pg_relation_size`","D":"`pg_database_size`"}'::jsonb, 'D', 'В практике курса так проверяют, насколько выросла база после создания таблиц.', '{"A":"Размер табличного пространства, а не базы.","B":"Полный размер одной таблицы с индексами.","C":"Размер слоя одного отношения, а не базы.","D":"Возвращает размер всей базы данных."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Как явно указать схему объекта в запросе?', '{"A":"Через имя базы данных: база.имя","B":"Через точку: схема.имя","C":"Только через параметр search_path","D":"Через двоеточие: схема:имя"}'::jsonb, 'B', 'Без квалификатора имя ищется по пути поиска.', '{"A":"В одном подключении доступна только одна база, и такая запись не указывает схему.","B":"Квалифицированное имя однозначно определяет схему.","C":"Путь поиска нужен для имён без схемы, а явное указание схемы работает всегда.","D":"Такого синтаксиса нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Таблица t есть в схемах app и public, доступ к обеим схемам есть, временной таблицы t нет, search_path = app, public. Из какой схемы возьмётся t в запросе SELECT * FROM t?', '{"A":"Из public: она используется по умолчанию","B":"Запрос завершится ошибкой неоднозначности","C":"Из обеих сразу","D":"Из app: она стоит в пути поиска раньше"}'::jsonb, 'D', 'Можно провести аналогию с переменной PATH в операционной системе.', '{"A":"Порядок задаёт search_path, а не имя схемы.","B":"Неоднозначности нет: берётся первая по порядку.","C":"Имя разрешается в один объект.","D":"Схемы перебираются слева направо до первой найденной."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Допишите команду, чтобы приоритет имела схема с именем пользователя, а затем app:
```
SET search_path = ___;
```', '{"A":"`app, \"$user\"`","B":"`\"$user\", app`","C":"`$user, app`","D":"`user, app`"}'::jsonb, 'B', 'Это одно из заданий практики курса.', '{"A":"Тогда приоритет будет у схемы app.","B":"Подстановку имени пользователя записывают в двойных кавычках.","C":"Без двойных кавычек $user не распознаётся как подстановка.","D":"Без кавычек и знака $ это не подстановка имени пользователя."}'::jsonb
) AS n(category_id, question_text, options, correct_answer, explanation, option_notes)
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
DECLARE n integer;
BEGIN
    SELECT count(*) INTO n FROM questions WHERE option_notes IS NOT NULL AND category_id IN (SELECT id FROM categories WHERE left(name, 3) IN ('05.', '06.', '07.', '08.'));
    IF n < 54 THEN
        RAISE EXCEPTION 'Ожидалось не меньше 54 вопросов с пояснениями в темах 05–08, найдено %', n;
    END IF;
END
$check$;

COMMIT;
